head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = "ULDSTF05960.xml";
scwin.pMenuID = $c.cm.InfoMenuID();
scwin.fn_GetPar, scwin.fn_SetPar, scwin.fr_SecuGrpId;
scwin.gIsurCd, scwin.gIsurNm, scwin.gInputRnd, scwin.gGubnStat, scwin.gAcptNo;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISUR_CD.getValue(); // 발행기관코드값
    arrPar[1] = txb_COM_NM.getValue(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤
    arrPar[3] = "9"; // 회사코드팝업 전체데이터
    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].COM_NM);
    }
};
scwin.fn_list_sync = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        var url = "/SectionTypeChange.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listSectAhthQual&inputMessageId=SECT_AHTH_QUAL_INOUT";
        url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
        url += "&LIST_DD=" + $c.stf.getObjectValue(edt_SDate);
        dts_List_1.DataID = encodeURI(url);
        dts_List_1.Reset();
        $c.cm.ShowWin(grd_List_1);
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        var url = "/SectionTypeChange.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listNewGrwthCom&inputMessageId=SECT_AHTH_QUAL_INOUT";
        url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
        url += "&LIST_DD=" + $c.stf.getObjectValue(edt_SDate);
        dts_List_2.DataID = encodeURI(url);
        dts_List_2.Reset();
        $c.cm.ShowWin(grd_List_2);
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        var url = "/SectionTypeChange.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listHdnChamp&inputMessageId=SECT_AHTH_QUAL_INOUT";
        url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
        url += "&LIST_DD=" + $c.stf.getObjectValue(edt_SDate);
        dts_List_3.DataID = encodeURI(url);
        dts_List_3.Reset();
        $c.cm.ShowWin(grd_List_3);
    }
};
scwin.fn_OpenDetail = async function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        await $c.frame.CreateDialogFrame("STOCK_LISTING", "/lstproc/ULDSTF05961.gfm?nIndex=1", " 인증및자격 관리", 200, 0, 820, 860, "window");
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        await $c.frame.CreateDialogFrame("STOCK_LISTING", "/lstproc/ULDSTF05962.gfm?nIndex=2", "라이징스타 관리", 200, 0, 700, 350, "window");
    }
};
scwin.fn_setContnId = function(obj) {
    if (eval(obj) > 0) {
        //그리드에서 선택시
        scwin.gIsurCd = dts_List_1.getCellData(eval(obj), "ISUR_CD");
        scwin.gIsurNm = dts_List_1.getCellData(eval(obj), "ISUR_NM");
        scwin.gInputRnd = dts_List_1.getCellData(eval(obj), "INPUT_RND");
        scwin.gAcptNo = dts_List_1.getCellData(eval(obj), "ACPT_NO");
        scwin.gGubnStat = "U";
    }
};
scwin.fn_filedown = function(dtsObj) {
    var discls_doc_no = dtsObj.getCellData(dtsObj.getFocusedRowIndex(), "DISCLS_DOC_NO");
    var acpt_no = dtsObj.getCellData(dtsObj.getFocusedRowIndex(), "ACPT_NO");
    var attach_seq = dtsObj.getCellData(dtsObj.getFocusedRowIndex(), "ATTACH_SEQ");
    if (discls_doc_no != "") {
        //문서번호
        location.href = "/filedownload.do?file_id=" + discls_doc_no + "&attach_seq=" + attach_seq + "&gubun=12";
    }
};



/*
	일괄등록
*/
scwin.fn_input = async function() {
    await $c.frame.CreateDialogFrame("ULDSTF05963", "/lstproc/ULDSTF05963.gfm", "라이징스타 등록", 300, 200, 980, 645, "window");
};
scwin.MaxTab_01_OnSelChanged = function(nIndex) {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue(vCurDate);
    if (MaxTab_01.getSelectedTabIndex() == 3) {
        $c.stf.showObj(btn_Input, true);
    } else {
        $c.stf.showObj(btn_Input, false);
    }
    if (MaxTab_01.getSelectedTabIndex() == 2) {
        $c.stf.showObj(btn_New, false);
    } else {
        $c.stf.showObj(btn_New, true);
    }
    scwin.fn_list_sync();
};
scwin.img_COM_NM_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsur;
    scwin.fn_SetPar = fn_SetParIsur;
    $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
};
scwin.txb_ISUR_CD_onblur = function() {
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.btn_New_onclick = function() {
    scwin.gGubnStat = "I"; //입력팝업
    scwin.fn_OpenDetail();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List_1);
};
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List_2);
};
scwin.dts_List_3_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List_3);
};
scwin.dts_List_1_OnLoadError = function() {
    $c.stf.alert_error(dts_List_1);
};
scwin.dts_List_2_OnLoadError = function() {
    $c.stf.alert_error(dts_List_2);
};
scwin.dts_List_3_OnLoadError = function() {
    $c.stf.alert_error(dts_List_3);
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        $c.data.downloadGridViewExcel(grd_List_1, "소속부 인증및 자격", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        $c.data.downloadGridViewExcel(grd_List_2, "기술성장기업", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        $c.data.downloadGridViewExcel(grd_List_3, "스타라이징", "", "8");
    }
};
scwin.grd_List_1_OnDblClick = function(row, colid) {
    if (colid == "ISUR_NM") {
        scwin.fn_setContnId(row);
        scwin.fn_OpenDetail();
    } else if (colid == "SAVE_FILE_NM") {
        scwin.fn_filedown(dts_List_1);
    }
};
scwin.grd_List_3_OnDblClick = function(row, colid) {
    if (row == 0) return;
    scwin.gIsurCd = dts_List_3.getCellData(row, "ISUR_CD");
    scwin.gIsurNm = dts_List_3.getCellData(row, "ISUR_NM");
    scwin.gInputRnd = dts_List_3.getCellData(row, "INPUT_RND");
    scwin.gGubnStat = "U";
    scwin.fn_OpenDetail();
};
scwin.gform_onload = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue(vCurDate);
    $c.cm.PanelToGroupBox(panel_Top);
    $c.stf.showObj(btn_Input, false);
    scwin.fn_list_sync();
};
scwin.btn_Input_onclick = function() {
    scwin.fn_input();
};
